// src/pages/Auth.jsx
import React, { useState } from 'react';


const Auth = () => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (isSignUp) {
        if (!formData.name  ||!formData.password || !formData.confirmPassword) {
          setError("Please fill in all fields.");
          setIsLoading(false);
          return;
        }
        if (formData.password !== formData.confirmPassword) {
          setError("Passwords don't match!");
          setIsLoading(false);
          return;
        }
                     

        console.log('User attempting to Sign Up with:', formData);
        await new Promise(resolve => setTimeout(resolve, 1500));
        console.log("Sign up simulated successfully!");
        alert("Sign up successful! Now you can sign in.");
        setIsSignUp(false);
        setFormData({ name: '', email: '', password: '', confirmPassword: '' });

      } else {
        if (!formData.email || !formData.password) {
          setError("Please enter your email and password.");
          setIsLoading(false);
          return;
        }

        console.log('User attempting to Sign In with:', { email: formData.email, password: formData.password });
        await new Promise(resolve => setTimeout(resolve, 1500));
        console.log("Sign in simulated successfully!");
        alert("Sign in successful!");
        setFormData({ name: '', email: '', password: '', confirmPassword: '' });
      }
    } catch (err) {
      console.error("Authentication error:", err);
      setError("An unexpected error occurred. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const styles = {
    container: {
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      minHeight: '100vh',
      backgroundColor: '#f0f2f5',
      fontFamily: 'Arial, sans-serif',
    },
    authBox: {
      backgroundColor: '#ffffff',
      padding: '40px',
      borderRadius: '8px',
      boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)',
      width: '100%',
      maxWidth: '400px',
      textAlign: 'center',
    },
    title: {
      marginBottom: '30px',
      color: '#333',
      fontSize: '28px',
    },
    form: {
      display: 'flex',
      flexDirection: 'column',
      gap: '15px',
    },
    input: {
      padding: '12px 15px',
      border: '1px solid #ddd',
      borderRadius: '5px',
      fontSize: '16px',
      width: 'calc(100% - 30px)',
    },
    button: {
      padding: '12px 20px',
      backgroundColor: '#007bff',
      color: '#fff',
      border: 'none',
      borderRadius: '5px',
      fontSize: '18px',
      cursor: 'pointer',
      marginTop: '10px',
      transition: 'background-color 0.3s ease',
    },
    buttonDisabled: {
      backgroundColor: '#cccccc',
      cursor: 'not-allowed',
    },
    errorText: {
      color: '#dc3545',
      marginBottom: '20px',
      fontSize: '14px',
    },
    toggleText: {
      marginTop: '25px',
      color: '#555',
      fontSize: '15px',
    },
    toggleLink: {
      color: '#007bff',
      textDecoration: 'none',
      cursor: 'pointer',
      fontWeight: 'bold',
      transition: 'color 0.3s ease',
    },
  };

  return (
    <div style={styles.container}>
      <div style={styles.authBox}>
        <h2 style={styles.title}>{isSignUp ? 'Sign Up' : 'Sign In'}</h2>

        {error && <p style={styles.errorText}>{error}</p>}
        <form onSubmit={handleSubmit} style={styles.form}>
          {isSignUp && (
            <input
              type="text"
              name="name"
              placeholder="Name"
              value={formData.name}
              onChange={handleChange}
              style={styles.input}
              disabled={isLoading}
            />
          )}
          <input
            type="email
 
          email"
            name="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            style={styles.input}
            disabled={isLoading}
          />
          <input
            type="password"
            name="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            style={styles.input}
            disabled={isLoading}
          />
          {isSignUp && (
            <input
              type="password"
              name="confirmPassword"
              placeholder="Confirm Password"
              value={formData.confirmPassword}
              onChange={handleChange}
              style={styles.input}
              disabled={isLoading}
            />
          )}

          <button type="submit" style={isLoading ? { ...styles.button, ...styles.buttonDisabled } : styles.button} disabled={isLoading}>
            {isLoading ? 'Loading...' : (isSignUp ? 'Sign Up' : 'Sign In')}
          </button>
        </form>

        <p style={styles.toggleText}>
          {isSignUp ? "Already have an account?" : "Don't have an account?"}{' '}
          <span
            onClick={() => {
              setIsSignUp(!isSignUp);
              setError('');
              setFormData({ name: '', email: '', password: '', confirmPassword: '' });
            }}
            style={styles.toggleLink}
          >
            {isSignUp ? 'Sign In' : 'Sign Up'}
          </span>
        </p>
      </div>
    </div>
  );
};

export default Auth;
